package kr.workbench;
import java.util.*;
public final class EnvironmentDiscoveryTest {
 static int checks;static void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;System.out.println("PASS "+message);}
 static EnvironmentCatalog.Candidate candidate(List<EnvironmentCatalog.Candidate> list,String suffix){return list.stream().filter(c->c.url().endsWith(suffix)).findFirst().orElseThrow();}
 public static void main(String[] args){
  var catalog=new EnvironmentCatalog();var api=catalog.observe("https://test/spec.json","Content-Type: application/json","{\"openapi\":\"3.0.0\",\"servers\":[{\"url\":\"/portal/api\"},{\"url\":\"https://outside.test\"}],\"paths\":{\"/reports\":{\"get\":{}},\"/users/{id}\":{\"get\":{}},\"/write\":{\"post\":{}},\"/override\":{\"get\":{\"servers\":[{\"url\":\"/other\"}]}}}}");
  var candidates=catalog.candidates(api,"",false,300);check(candidate(candidates,"/portal/api/reports").source().equals("OpenAPI GET 선언"),"OpenAPI base path");check(candidate(candidates,"/other/override").score()==100,"operation server override");check(candidates.stream().noneMatch(c->c.url().contains("{id}")||c.url().endsWith("/write")),"templates and write-only operations excluded");check(candidates.stream().allMatch(c->c.url().startsWith("https://test/")),"external schema servers excluded");check(api.prefixes.contains("/portal/api"),"schema application prefix learned");
  var legacy=catalog.observe("https://legacy.test/spec.json","","{\"swagger\":\"2.0\",\"host\":\"legacy.test\",\"basePath\":\"/v2\",\"paths\":{\"/audit\":{\"get\":{}}}}");check(candidate(catalog.candidates(legacy,"",false,300),"/v2/audit").score()==100,"Swagger 2 base path");
  var actuator=catalog.observe("https://spring.test/manage","Content-Type: application/vnd.spring-boot.actuator.v3+json","{\"_links\":{\"self\":{\"href\":\"https://spring.test/manage\"},\"health\":{\"href\":\"https://spring.test/manage/health\"},\"detail\":{\"href\":\"https://spring.test/manage/health/{component}\",\"templated\":true}}}");
  candidates=catalog.candidates(actuator,"",false,300);check(candidate(candidates,"/manage/health").source().equals("Actuator 실제 링크"),"Actuator captured link");check(candidate(candidates,"/manage/env").score()==88,"renamed actuator root");check(candidates.stream().noneMatch(c->c.url().contains("{component}")),"templated Actuator link excluded");
  var robot=catalog.observe("https://robots.test/robots.txt","","User-agent: *\nDisallow: /internal/\nDisallow: /a*\nDisallow: https://outside.test/secret\nSitemap: /sitemap.xml");candidates=catalog.candidates(robot,"",false,300);check(candidate(candidates,"/internal/").source().contains("robots"),"robots directive discovery");check(candidates.stream().noneMatch(c->c.url().contains("*")||c.url().contains("outside")),"robots wildcard and external exclusion");
  catalog.observe("https://robots.test/sitemap.xml","","<urlset><url><loc>https://robots.test/portal/settings?secret=hidden</loc></url></urlset>");check(candidate(catalog.candidates(robot,"",false,300),"/portal/settings").source().contains("sitemap"),"sitemap query values excluded");
  var config=catalog.observe("https://ui.test/docs/swagger-config","","{\"urls\":[{\"url\":\"../schema.json\"}]}");check(candidate(catalog.candidates(config,"",false,300),"/schema.json").source().contains("Swagger"),"relative swagger schema reference");
  var imported=catalog.observe("https://word.test/","","");var result=EnvironmentDiscovery.importWords(imported,"admin\n/admin\n/.env\nhttps://outside.test/a\n/../bad\n/%2e%2e/bad\n/query?secret=x\n/path/{id}\n# comment","SecLists sample.txt");check(result.accepted()==2&&result.skipped()==6,"wordlist normalization duplicates invalid paths: "+result);check(imported.detections.containsKey("가져온 경로 목록"),"wordlist category");check(catalog.candidates(imported,"",false,300).stream().allMatch(c->c.score()==40),"wordlist lacks observed evidence");
  catalog.feedback("https://word.test/admin",404,"HTTP 404 · 미발견");check(candidate(catalog.candidates(imported,"",false,300),"/admin").score()==-20,"404 feedback demotes candidate");
  catalog.feedback("https://word.test/.env",403,"HTTP 403 · 접근 제한");check(candidate(catalog.candidates(imported,"",false,300),"/.env").score()==48,"access-denied remains reviewable");
  String many=String.join("\n",java.util.stream.IntStream.range(0,800).mapToObj(i->"/p"+i).toList());EnvironmentDiscovery.importWords(imported,many,"large.txt");check(imported.discovered.size()==500,"discovery memory bounded");
  var fast=catalog.observe("https://fast.test/docs","","<title>FastAPI - Swagger UI</title>");check(fast.detections.containsKey("FastAPI"),"FastAPI fingerprint");check(candidate(catalog.candidates(fast,"",false,300),"/openapi.json").condition().contains("http"),"catalog source reference retained");
  var symfony=catalog.observe("https://symfony.test/","X-Debug-Token: 1234","");check(symfony.detections.containsKey("Symfony"),"Symfony header fingerprint");
  var aem=catalog.observe("https://aem.test/","","<script src='/etc.clientlibs/site.js'></script>");check(aem.detections.containsKey("Adobe Experience Manager"),"AEM resource fingerprint");
  String missing="<html><body>Not found /wb-missing-123</body></html>";var baseline=EnvironmentResponse.baseline(200,"Content-Type: text/html",missing,"https://test/wb-missing-123");
  check(EnvironmentResponse.state(200,"Content-Type: text/html","<html><body>Not found /admin</body></html>","https://test/admin",baseline).contains("없는 경로와 동일"),"reflected-path soft 404 comparison");check(EnvironmentResponse.state(200,"Content-Type: application/json","{}","https://test/admin",baseline).contains("응답 검토"),"different response not soft 404");
  check(EnvironmentResponse.state(403,"","","https://test/admin",baseline).contains("접근 제한"),"403 is access control not success");check(EnvironmentResponse.state(302,"Location: /login","","https://test/admin",baseline).contains("로그인 이동"),"login redirect");check(EnvironmentResponse.state(429,"","","https://test/admin",baseline).contains("요청 제한"),"rate limit");
  check(EnvironmentKnowledge.manualOnly("https://test/actuator/heapdump")&&!EnvironmentKnowledge.manualOnly("https://test/actuator/health"),"heavy diagnostics separated from batch");
  check(WorkbenchUi.tone("HTTP 200 · 없는 경로와 동일")==WorkbenchUi.Tone.WARNING,"soft 404 badge is not green");
  System.out.println("EnvironmentDiscoveryTest: "+checks+" checks passed");
 }
}
